"""Demo: recover the topological charge of a beam from field data
by numerical contour integration of the logarithmic derivative."""
from __future__ import annotations
import cmath, math
from typing import Callable

def oam_phase(L: int, theta: float) -> complex:
    return cmath.exp(1j * L * theta)

def winding_number(phi: Callable[[float], complex], n: int = 100_000) -> complex:
    two_pi = 2.0 * math.pi
    h = two_pi / n
    d = 1e-7
    def integrand(t: float) -> complex:
        return ((phi(t + d) - phi(t - d)) / (2 * d)) / phi(t)
    total = 0j
    prev = integrand(0.0)
    for k in range(1, n + 1):
        cur = integrand(k * h)
        total += 0.5 * (prev + cur) * h
        prev = cur
    return total / (two_pi * 1j)

if __name__ == "__main__":
    for L in [-2, -1, 0, 1, 3, 5]:
        w = winding_number(lambda t, L=L: oam_phase(L, t))
        print(f"charge L = {L:+d}  ->  winding = {w.real:+.4f}  (expected {L:+d})")

"""Demo: charge additivity and vortex annihilation under superposition.
Multiplying OAM fields adds their charges; opposite charges cancel."""
from __future__ import annotations
import cmath, math
from typing import Callable, List

def oam_phase(L: int, theta: float) -> complex:
    return cmath.exp(1j * L * theta)

def winding_number(phi: Callable[[float], complex], n: int = 80_000) -> float:
    two_pi = 2.0 * math.pi
    h = two_pi / n
    d = 1e-7
    def integ(t: float) -> complex:
        return ((phi(t + d) - phi(t - d)) / (2 * d)) / phi(t)
    tot = 0j; prev = integ(0.0)
    for k in range(1, n + 1):
        cur = integ(k * h); tot += 0.5 * (prev + cur) * h; prev = cur
    return (tot / (two_pi * 1j)).real

def total_charge(charges: List[int]) -> float:
    def field(t: float) -> complex:
        p = 1 + 0j
        for L in charges:
            p *= oam_phase(L, t)
        return p
    return winding_number(field)

if __name__ == "__main__":
    for group in [[1, 2], [3, -1, -2], [5, -5], [2, 2, -1]]:
        w = total_charge(group)
        note = "  (singularity-free!)" if abs(w) < 1e-6 else ""
        print(f"charges {group}  ->  total winding = {w:+.4f}"
              f"  (sum = {sum(group):+d}){note}")

"""Demo: map the on-axis phase singularity of a vortex beam.
The amplitude r^|L| exp(iLtheta) vanishes at r=0 iff L != 0, and the
phase winds L times around the dark core."""
from __future__ import annotations
import cmath, math

def beam_amplitude(L: int, r: float, theta: float) -> complex:
    return (r ** abs(L)) * cmath.exp(1j * L * theta)

def intensity_grid(L: int, n: int = 21, extent: float = 1.0) -> None:
    print(f"Intensity |A|^2 for charge L = {L} (dark '.' = low, '#' = high):")
    ramp = " .:-=+*#%@"
    for iy in range(n):
        y = extent * (2 * iy / (n - 1) - 1)
        row = ""
        for ix in range(n):
            x = extent * (2 * ix / (n - 1) - 1)
            r = math.hypot(x, y); th = math.atan2(y, x)
            inten = abs(beam_amplitude(L, r, th)) ** 2
            row += ramp[min(len(ramp) - 1, int(inten * (len(ramp) - 1)))]
        print("  " + row)
    print()

if __name__ == "__main__":
    for L in [0, 1, 2, 3]:
        intensity_grid(L)
